"""Construye y ejecuta el notebook de la prueba mediante un kernel Python real."""
from pathlib import Path
import sys

import nbformat as nbf
from nbclient import NotebookClient

ROOT = Path(__file__).resolve().parents[1]


def main():
    notebook = nbf.v4.new_notebook()
    md = nbf.v4.new_markdown_cell
    code = nbf.v4.new_code_cell
    notebook.cells = [
        md('# Primera prueba: anticipar crecimiento poblacional con censos\n\nProyecto individual tutorado con Pablo Valenzuela. Clasificación supervisada temporal, usando datos oficiales del INE. **El resultado de esta prueba fue negativo frente a la continuidad de tendencia.** Se documenta el proceso sin ajustar el experimento con la prueba final.'),
        md('## 1. Pregunta, unidad y respuesta\n\n¿Podemos clasificar si una comuna tendrá un crecimiento medio de al menos 1% anual usando población y estructura por edades del censo inicial? Cada ejemplo es una **comuna en un período**, no un habitante. El umbral es una decisión del proyecto, no una categoría oficial. La tasa es `(P_final/P_inicial)**(1/años)-1`.\n\nEntrenamiento: 1992→2002. Validación: 2002→2017. Prueba: 2017→2024. Las mismas comunas se repiten porque se evalúa cambio temporal, no comunas desconocidas. Esta es una reconstrucción retrospectiva, no un pronóstico emitido en 2017.'),
        code("from pathlib import Path\nimport sys, json\nimport pandas as pd\nimport numpy as np\nimport sklearn\nfrom IPython.display import display, Image\nROOT = Path.cwd()\nif not (ROOT / 'experiments').exists(): ROOT = ROOT.parent\nsys.path.insert(0, str(ROOT / 'experiments'))\nimport crecimiento_censal as study\nOUT = ROOT / 'results/crecimiento_censal'\nprint('Python:', sys.version.split()[0], 'scikit-learn:', sklearn.__version__)\nREGENERAR = False\nif REGENERAR: study.run()\nprotocol = json.loads((ROOT / 'experiments/protocolo_crecimiento.json').read_text())\nsummary = json.loads((OUT / 'resumen.json').read_text())\nquality = json.loads((OUT / 'calidad_datos.json').read_text())\nprofiles = pd.read_csv(OUT / 'perfiles_censales.csv')"),
        md('## 2. Procedencia y preparación\n\nSe consultaron tabulados agregados de los censos 1992, 2002 y 2017 mediante REDATAM del INE. Se conservan HTML crudos, parámetros de consulta y hashes. En 1992 y 2002 se usa comuna de residencia habitual (`VIVEHAB`), no solo lugar de empadronamiento. En 2017 se suman quienes viven en la comuna donde fueron censados (`P10=1 o 2`, tabulados por comuna) y quienes fueron censados en otra comuna (tabulado por `P10COMUNA`). Los códigos sin comuna identificada quedan fuera, sin imputar residencia.\n\nLa composición etaria utiliza la misma definición de menores de 15 y 65 o más. Las variantes ortográficas se resuelven mediante equivalencias explícitas. No se emparejan automáticamente nombres parecidos. Se excluyen cambios territoriales conocidos e identidades ambiguas. **Todavía falta certificar todos los límites con cartografías históricas.**'),
        code("sources = json.loads((ROOT / 'data/raw/ine/crecimiento/fuentes.json').read_text())\ndisplay(pd.DataFrame([{k:r.get(k) for k in ('file','url','bytes','sha256')} for r in sources['files']]))\nprint('Contraste independiente de 2017:', quality['independent_2017_check'])\nprint('Comunas incluidas:', quality['included_communes'], 'excluidas:', len(quality['exclusions']))\ndisplay(pd.DataFrame(quality['exclusions'])[['name','reason']])"),
        md('## 3. Exploración y tipos de variables\n\nPoblación: recuento discreto, escala de razón. Proporciones por edad: variables numéricas de razón. Código y nombre comunal: identificadores nominales, excluidos del modelo. Año identifica la etapa, también se excluye como entrada. La clase objetivo es binaria. No se requieren imputación ni escalado ajustado sobre toda la base: se usan perfiles completos y tres entradas numéricas.'),
        code("display(profiles.groupby('year').agg(comunas=('code','nunique'), residentes=('population','sum'), menores_15=('young','sum'), personas_65_mas=('old','sum')))\ndisplay(pd.DataFrame([{'etapa':stage,'menor_1_por_ciento':values['class_counts'][0],'al_menos_1_por_ciento':values['class_counts'][1]} for stage,values in [('entrenamiento',summary['train']),('validacion',summary['validation'][summary['selected']]),('prueba',summary['test']['modelo'])]]))\ndisplay(profiles[['population','young','old']].describe())"),
        md('## 4. Separación temporal y prevención de filtración\n\nX contiene `log(1+población_inicial)`, proporción de menores de 15 y proporción de 65 o más del inicio. La población final solo construye y; no se entrega al clasificador. Un aumento de habitantes dentro del mismo período no es una variable predictora. No se divide aleatoriamente una tabla que mezcle todos los años.\n\nLa configuración se eligió usando 314 ejemplos de entrenamiento y 314 de validación. Después se reentrenó solo la elegida con esos 628 ejemplos. La elección, los parámetros y las métricas de validación se guardaron **antes de leer las cifras finales de 2024**. Las tablas fueron descargadas previamente, pero no se calcularon las etiquetas de prueba para elegir. Los datos censales son observaciones de cada período; se utiliza su publicación actual para este ejercicio retrospectivo.'),
        code("historical = profiles.loc[profiles.year < 2024]\ninitial_train, X_train, y_train, _ = study.interval(historical,1992,2002)\ninitial_val, X_val, y_val, _ = study.interval(historical,2002,2017)\nassert list(X_train.columns) == protocol['features']\nassert all('population_final' not in c for c in X_train.columns)\nassert np.isfinite(X_train.to_numpy()).all()\nprint('X de entrenamiento:',X_train.shape,'y:',y_train.shape)\ndisplay(X_train.head())\ndisplay(pd.DataFrame(protocol['alternatives']))"),
        md('## 5. Entrenamiento y selección\n\nSe comparan un árbol limitado a profundidad 3 y un bosque de 300 árboles limitado a profundidad 5. Los tamaños mínimos de hoja limitan el sobreajuste y se ponderan clases. Se selecciona por F1 macro de validación, con exactitud balanceada y simplicidad como desempates.\n\nReferencias: clase mayoritaria del entrenamiento y continuidad de la clase de crecimiento del intervalo anterior. La continuidad dispone de una tasa histórica adicional, que los clasificadores de esta versión no reciben como entrada. Es información disponible al inicio y una referencia práctica exigente. Esta diferencia limita cualquier conclusión general sobre los algoritmos.'),
        code("models = study.make_models(protocol)\ncomparisons = []\nfor name, classifier in models.items():\n    classifier.fit(X_train,y_train)\n    observed = study.metrics(y_val,classifier.predict(X_val))\n    assert np.isclose(observed['f1_macro'],summary['validation'][name]['f1_macro'])\n    comparisons.append({'alternativa':name,'F1_macro_validacion':observed['f1_macro'],'exactitud_balanceada':observed['balanced_accuracy'],'exactitud':observed['accuracy']})\ndisplay(pd.DataFrame(comparisons))\nclosed = json.loads((OUT / 'seleccion_cerrada.json').read_text())\nprint('Elección cerrada:',closed['selected'],'prueba usada para elegir:',closed['test_used_for_selection'])"),
        md('## 6. Prueba final y errores\n\n2024 aporta el resultado observado posterior a las entradas de 2017. La elección sigue siendo la de validación, aunque una referencia resulte mejor en prueba. No se modificaron variables, umbral ni parámetros para elevar las métricas de 2024. F1 macro da el mismo peso a las dos clases. La matriz muestra filas reales y columnas predichas.'),
        code("display(pd.DataFrame([{'alternativa':name,**{k:v[k] for k in ('n','f1_macro','balanced_accuracy','accuracy')}} for name,v in summary['test'].items()]))\ndisplay(pd.DataFrame(summary['test']['modelo']['confusion'],index=['Real <1%','Real ≥1%'],columns=['Predice <1%','Predice ≥1%']))\ndisplay(pd.DataFrame(summary['test']['modelo']['classes']).T)\ndisplay(Image(filename=str(OUT / 'evaluacion.png')))\npredictions = pd.read_csv(OUT / 'predicciones_prueba.csv')\ndisplay(predictions[['name','population','actual_population','predicted_class','actual_class','actual_rate','correct']].head(8))"),
        md('## 7. Resultado, utilidad y límites\n\nEl bosque fue la mejor alternativa entrenada según validación. En prueba final obtuvo **F1 macro 0,528** y **169 aciertos de 314**. La continuidad de tendencia obtuvo **0,663** y **213 de 314**. Esta versión no aporta mejora frente a esa referencia. Ese resultado es parte del experimento, no se oculta.\n\nEl prototipo permite consultar una comuna, ver las tres entradas, obtener la clasificación y revelar el resultado real. Incluye un escenario 2024→2031 expresamente experimental, sin resultado observado y sin validación futura. Usa el mismo modelo entrenado antes de la prueba: no se reutilizan las etiquetas de 2024 para reentrenarlo. El score interno no es una probabilidad calibrada.\n\nUna futura versión podría incorporar crecimiento anterior, más períodos y otras variables pertinentes. Se debe registrar un nuevo protocolo y una nueva estrategia de evaluación: **la prueba de 2024 ya fue observada y no volvería a ser una prueba final intacta**. Pocos intervalos, diferencias de duración, no respuesta, cambios de cobertura y geografía limitan la inferencia. La aprobación académica y el calendario individual deben acordarse con Pablo Valenzuela.'),
        md('## Fuentes\n\n- [INE, censos y REDATAM](https://www.ine.gob.cl/estadisticas-por-tema/demografia-y-poblacion/censo-de-poblacion-y-vivienda).\n- [Tablas Censo 2024](https://censo2024.ine.gob.cl/resultados/).\n- [Comparación de población censada y residente](https://censo2024.ine.gob.cl/wp-content/uploads/2025/04/N3_Nota_Tecnica_Comparacion_Poblacion_CPV2024.pdf).\n- [Ley 20.578, cambios de límites](https://www.bcn.cl/leychile/navegar?idNorma=1038291).\n- [Ley 20.721, Vicuña y Paihuano](https://www.bcn.cl/leychile/navegar?idNorma=1058812).\n\nAtribución: INE, Censos de Población y Vivienda. Tabulados y derivados bajo CC BY-SA 4.0, con cambios documentados. No se utilizan proyecciones como observaciones, ni registros privados de CliniPets.'),
    ]
    notebook.metadata.kernelspec = {'display_name': 'Python 3', 'language': 'python', 'name': 'python3'}
    notebook.metadata.language_info = {'name': 'python', 'version': sys.version.split()[0]}
    # Usar este entorno mediante un spec temporal, sin registrar kernels globales.
    import tempfile
    from jupyter_client.kernelspec import KernelSpecManager
    with tempfile.TemporaryDirectory() as tmp:
        spec = Path(tmp) / 'censo-python'
        spec.mkdir()
        (spec / 'kernel.json').write_text(__import__('json').dumps({'argv': [sys.executable,'-m','ipykernel_launcher','-f','{connection_file}'], 'display_name':'Python censos','language':'python'}))
        manager = KernelSpecManager(kernel_dirs=[tmp])
        client = NotebookClient(notebook, timeout=120, resources={'metadata': {'path': str(ROOT)}}, kernel_name='censo-python')
        client.km = __import__('jupyter_client').KernelManager(kernel_name='censo-python', kernel_spec_manager=manager)
        client.execute()
    nbf.validate(notebook)
    target = ROOT / 'experiments/estudio_crecimiento_censal.ipynb'
    nbf.write(notebook, target)
    print('Notebook ejecutado:', target)


if __name__ == '__main__':
    main()
